#!/bin/bash\n\n# Elenty.app Expo Deployment Script\n# ===================================\n# هذا الملف يحتوي على أوامر البناء والنشر\n\nset -e\n\necho \"🚀 بدء عملية نشر Elenty.app\"\necho \"================================\"\n\n# الألوان\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# 1. التحقق من الأدوات المطلوبة\necho -e \"${BLUE}📋 التحقق من الأدوات المطلوبة...${NC}\"\n\nif ! command -v eas &> /dev/null; then\n    echo -e \"${RED}❌ EAS CLI غير مثبت${NC}\"\n    echo \"تثبيت بـ: npm install -g eas-cli\"\n    exit 1\nfi\n\nif ! command -v npm &> /dev/null; then\n    echo -e \"${RED}❌ npm غير مثبت${NC}\"\n    exit 1\nfi\n\necho -e \"${GREEN}✅ جميع الأدوات موجودة${NC}\"\n\n# 2. التحقق من بيانات التطبيق\necho -e \"\\n${BLUE}📝 التحقق من بيانات التطبيق...${NC}\"\n\nif [ ! -f \"app.json\" ]; then\n    echo -e \"${RED}❌ ملف app.json غير موجود${NC}\"\n    exit 1\nfi\n\necho -e \"${GREEN}✅ تم العثور على app.json${NC}\"\n\n# 3. تثبيت المتعلقات\necho -e \"\\n${BLUE}📦 تثبيت المتعلقات...${NC}\"\ncd Elenty.app\nnpm install\necho -e \"${GREEN}✅ تم تثبيت المتعلقات${NC}\"\n\n# 4. فحص الأخطاء\necho -e \"\\n${BLUE}🔍 فحص أخطاء TypeScript...${NC}\"\nnpx tsc --noEmit\necho -e \"${GREEN}✅ لا توجد أخطاء${NC}\"\n\n# 5. بناء التطبيق\necho -e \"\\n${BLUE}🔨 بناء التطبيق...${NC}\"\necho -e \"${YELLOW}اختر المنصة:${NC}\"\necho \"1) Android فقط\"\necho \"2) iOS فقط\"\necho \"3) كلا المنصتين\"\nread -p \"اختيارك: \" platform\n\ncase $platform in\n    1)\n        echo -e \"${BLUE}بناء Android...${NC}\"\n        eas build --platform android --release-channel production\n        ;;\n    2)\n        echo -e \"${BLUE}بناء iOS...${NC}\"\n        eas build --platform ios --release-channel production\n        ;;\n    3)\n        echo -e \"${BLUE}بناء كلا المنصتين...${NC}\"\n        eas build --platform all --release-channel production\n        ;;\n    *)\n        echo -e \"${RED}اختيار غير صحيح${NC}\"\n        exit 1\n        ;;\nesac\n\necho -e \"${GREEN}✅ تم البناء بنجاح${NC}\"\n\n# 6. النشر\necho -e \"\\n${BLUE}📤 هل تريد النشر الآن؟${NC}\"\nread -p \"(y/n): \" submit\n\nif [ \"$submit\" = \"y\" ]; then\n    case $platform in\n        1)\n            echo -e \"${BLUE}نشر على Google Play...${NC}\"\n            eas submit --platform android --latest\n            ;;\n        2)\n            echo -e \"${BLUE}نشر على App Store...${NC}\"\n            eas submit --platform ios --latest\n            ;;\n        3)\n            echo -e \"${BLUE}نشر على المتاجر...${NC}\"\n            eas submit --platform android --latest\n            eas submit --platform ios --latest\n            ;;\n    esac\n    \n    echo -e \"${GREEN}✅ تم النشر بنجاح${NC}\"\nelse\n    echo -e \"${YELLOW}⏭️  تم تخطي النشر${NC}\"\nfi\n\necho -e \"\\n${GREEN}🎉 انتهت العملية${NC}\"\necho \"================================\"\n